"""全局配置模块。本模块负责在项目启动时：1. 读取项目根目录下的 `.env` 文件，把里面的键值对写入环境变量；2. 把这些环境变量收敛到一个只读的 `Settings` 数据类里，供全项目统一引用。教学要点：- 使用 `dataclass(frozen=True)` 让配置对象“不可变”，避免运行时被误改。- 所有敏感信息（API Key 等）都从环境变量读取，不写死在代码里。- 提供合理默认值，方便在缺省情况下也能跑通大部分流程。"""from __future__ import annotations  # 启用延迟注解求值import os  # 读取环境变量 os.getenvfrom dataclasses import dataclass  # 声明 Settings 数据类from pathlib import Path  # 跨平台路径处理from dotenv import load_dotenv  # 从 .env 文件加载变量到 os.environ# 项目根目录：当前文件是 core/settings.py，parents[1] 即上一级（项目根）。PROJECT_ROOT = Path(__file__).resolve().parents[1]  # demos-travel-planner-agent 目录绝对路径# 加载根目录下的 .env 文件，使 os.getenv 能读到里面配置的变量。load_dotenv(PROJECT_ROOT / ".env")  # 导入本模块时即执行，全局生效@dataclass(frozen=True)  # frozen=True：实例创建后字段不可修改，当作只读配置快照class Settings:  # 全项目统一的配置数据类，字段对应各环境变量    """集中管理所有可配置项的只读配置对象。    每个字段都对应一个环境变量，并给出默认值；`frozen=True` 表示实例一旦创建就不能再修改。    """    # ===== 大模型（Qwen / DashScope，兼容 OpenAI 协议）=====    dashscope_api_key: str | None = os.getenv("DASHSCOPE_API_KEY")  # LLM 访问密钥    qwen_model: str = os.getenv("QWEN_MODEL", "qwen-plus")  # 使用的模型名    qwen_base_url: str = os.getenv(  # OpenAI 兼容接口地址，默认指向 DashScope        "QWEN_BASE_URL",        "https://dashscope.aliyuncs.com/compatible-mode/v1",    )  # getenv 第二参数为未配置时的默认值    # ===== 外部工具 API =====    tavily_api_key: str | None = os.getenv("TAVILY_API_KEY")  # 联网搜索    amap_api_key: str | None = os.getenv("AMAP_API_KEY")  # 高德地图（地理编码/天气/公交）    map_timeout_seconds: float = float(os.getenv("MAP_TIMEOUT_SECONDS", "5"))  # 地图请求超时（秒）    # ===== 情感咨询 RAG 相关（向量库 Chroma）=====    chroma_host: str | None = os.getenv("CHROMA_HOST")  # Chroma 服务地址    chroma_port: int = int(os.getenv("CHROMA_PORT", "8000"))  # Chroma 服务端口    emotion_collection_name: str = os.getenv("EMOTION_COLLECTION_NAME", "emotion_books")  # 向量集合名    emotion_embed_model: str = os.getenv("EMOTION_EMBED_MODEL", "text-embedding-v3")  # 向量化模型    emotion_embed_dim: int = int(os.getenv("EMOTION_EMBED_DIM", "1024"))  # 向量维度    emotion_similarity_top_k: int = int(os.getenv("EMOTION_SIMILARITY_TOP_K", "4"))  # 检索返回条数    # ===== 情感咨询会话记忆（Redis）=====    redis_url: str | None = os.getenv("REDIS_URL")  # Redis 连接串    emotion_redis_key_prefix: str = os.getenv("EMOTION_REDIS_KEY_PREFIX", "emotion:chat:")  # 会话 key 前缀    emotion_memory_ttl_seconds: int = int(os.getenv("EMOTION_MEMORY_TTL_SECONDS", "604800"))  # 记忆过期时间    emotion_memory_window_messages: int = int(os.getenv("EMOTION_MEMORY_WINDOW_MESSAGES", "20"))  # 参与推理的最近消息数    # 恋爱报告 PDF 输出目录（相对路径会在使用时拼到项目根下）。    emotion_reports_dir: Path = Path(        os.getenv("EMOTION_REPORTS_DIR", PROJECT_ROOT / "data" / "emotion_reports"))  # 报告存储目录# 全局唯一的配置单例，其他模块通过 `from core.settings import settings` 使用。settings = Settings()  # 模块加载时实例化，全项目共享同一配置快照